                            if v["supplier_id"] not in ahead or v["kind"] in ("accept", "walk_away")}
        # A supplier the arena had to answer by timeout comes first: after a final offer one more timeout
        # closes its thread (Azure P05: 70250 fell to 30.00 by timeout, then final, then walked away while we
        # bargained with another supplier). Accepting any supplier stays possible.
        def stale(sid):
            n = 0
            for m in reversed(threads[sid]):
                if not m.get("timeout_reply"):
                    break
                n += 1
            return n
        urgent = max(open_ones + [sid for sid in live if latest(threads[sid]).get("status") == "final_offer"],
